"""Reviewed regional additions, reproduced offline from retained official evidence."""
import json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
E=ROOT/'scripts/evidence'
S=json.loads((E/'acquired0710.json').read_text())
P={p['parkCode']:p['id'] for p in json.loads((ROOT/'docs/BASELINE0710.json').read_text())['units']}
OUT={'parks':{}}
def u(path):return 'https://www.nps.gov/'+path
def length(value,method):return dict(value=value,unit='mi',method=method)
def gain(value,method):return dict(value=value,unit='ft',method=method)
def conflict(field,detail,*paths):return dict(field=field,detail=detail,sources=[u(p) for p in paths])
def add(code,name,kind,path,description,anchors,related=(),**attrs):
 source=u(path);pages=[source]+[u(p) for p in related];evidence=[]
 for url in pages:
  p=S[url];assert not p.get('error'),url
  needles=anchors if url==source else [p['title'].splitlines()[0]]
  excerpts=[]
  for needle in needles:
   pos=p['text'].casefold().find(needle.casefold());assert pos>=0,(name,needle,url)
   excerpts.append(p['text'][max(0,pos-80):pos+len(needle)+400])
  evidence.append(dict(url=url,title=p['title'].splitlines()[0],retrievedAt=p['retrievedAt'],sourceUpdated=p['sourceUpdated'],excerpts=excerpts))
 record=dict(name=name,kind=kind,source=source,sourceKey=re.sub('[^a-z0-9]+','-',name.lower()).strip('-'),description=description,descriptionKind='summary',retrievedAt=S[source]['retrievedAt'],verificationStatus='official-source',evidence=dict(retainedFile='acquired0710.json',sources=evidence),**attrs)
 if related:record['relatedSources']=[u(p) for p in related]
 OUT['parks'].setdefault(P[code],{'attractions':[]})['attractions'].append(record)

alpo='alpo/planyourvisit/hiking-and-biking.htm'
add('alpo','Skew Arch Bridge Trail','trail',alpo,'Descend beside historic Incline 6 from the summit boardwalk to the angled stone bridge. The climb back follows the same hillside; the route also connects to the longer Inclines 6 to 10 system.',['Skew Arch Bridge Trail','1/3 mile long each way'],length=length(.33,'approximately one-third mile one way; decimal rounded, return not included'),terrain='Downhill to the bridge; uphill on return.',tags=['historic','hiking'])
add('alpo','Summit Level Trail','trail',alpo,'Follow the railroad trace between the heads of inclined planes 6 and 5, on the high crossing of the Allegheny Mountains. The route reaches the park boundary before continuing onto a township road.',['Summit Level Trail','a little over 3 miles'],length=length(3,'a little over 3 miles round trip; numeric value is a lower bound, not an exact survey'),terrain='Nearly flat railroad trace.',tags=['historic','hiking'])
add('alpo','Picnic Area Trail','trail',alpo,'A branch from the Summit Level railroad trace leads through woodland to the picnic area. The longer option loops back to the trace rather than simply returning along the short access branch.',['Picnic Area Trail','about one mile'],length=length(1,'approximately one mile for the full picnic-area loop returning via Summit Level; direct access is one-third mile'),routeType='loop',terrain='Mixed flat ground and steeper slopes.',tags=['historic','forest','hiking'])
add('alpo','Nature Loop Trail','trail',alpo,'Climb into the woods from the Summit Level near the Lemon House, reach one of the higher areas of the park, and circle down to the historic railroad trace.',['Nature Loop Trail','entire trail is about one mile'],length=length(1,'approximately one mile for the entire loop'),routeType='loop',terrain='Steep climbs through woodland.',tags=['forest','historic','hiking'])
add('alpo','Staple Bend Tunnel Trail','trail',alpo,'Walk or bicycle the limestone-dust railroad corridor from Mineral Point to the western tunnel portal. This detached park area interprets early railroad engineering rather than the summit inclined planes.',['Staple Bend Tunnel Trail','two mile walk','limestone dust'],related=['alpo/learn/historyculture/staplebend.htm'],length=length(2,'one way from the trailhead to the tunnel; source separately specifies a two-mile return'),surface='Limestone dust.',seasonalNotes='The tunnel history page reported an interior closure due to rockfall when retrieved. This is retained reference information, not live access status; check official conditions before entry.',tags=['historic','hiking'])
add('alpo','Lemon House Tavern','historic-site','alpo/planyourvisit/lemon-tavern.htm','Explore the restored first-floor tavern rooms where railroad travelers ate, rested and waited while their trains were prepared to cross the mountain. Access is on foot from the summit visitor area.',['period bar room','dining room'],tags=['historic','railroad'])
add('alpo','Engine House No. 6 Exhibit Shelter','museum','alpo/planyourvisit/engine-house-6.htm','See the preserved foundations beneath a shelter containing a reconstructed stationary engine, tow-rope machinery, gears and brakes. Tactile and interactive exhibits explain how inclined-plane rail transport worked.',['stationary engine','tactile exhibits'],tags=['historic','railroad','engineering'])
add('alpo','Staple Bend Tunnel','historic-site','alpo/learn/historyculture/staplebend.htm','Visit the portals of an early American railroad tunnel in the park’s detached Mineral Point section. Interpret the engineering at the end of the approach trail; interior access must be checked separately.',['Staple Bend Tunnel','rockfall'],seasonalNotes='The retained NPS page reports a rockfall closure of the tunnel interior and a bypass path. Do not infer that the interior is currently open.',tags=['historic','railroad','engineering'])

mh='hafe/planyourvisit/maryland-heights-trail.htm';mc='hafe/planyourvisit/murphy-chambers-farm-trail.htm';sn='hafe/planyourvisit/schoolhouse-ridge-north-trail.htm';vc='hafe/planyourvisit/visitor-center-to-lower-town-trail.htm'
add('hafe','Maryland Heights Trail','trail',mh,'Climb above the Potomac to a cliff overlook of Harpers Ferry, passing Civil War defenses and rocky woodland. The optional Stone Fort extension is a different, longer hike and is not included in the base overlook distance.',['quickest route','4.5 miles round trip','990 - 1788','1154'],length=length(4.5,'round trip from Lower Town / Master Armorer’s House to the overlook; excludes Stone Fort extension'),terrain='Steep climbs, boulders and a narrow rocky descent near the overlook.',seasonalNotes='The retained August 2026 page describes footbridge staircase construction and altered trailhead access. Verify official current conditions; the historic approach description is not a live access guarantee.',conflicts=[conflict('length','The source describes the Stone Fort extension as 6.5 miles in its introduction but 6.2 miles from Lower Town in its hike table. The 4.5-mile base overlook route agrees; extension distance remains unresolved.',mh),conflict('elevationGain','Quick facts give a 990–1788-foot range, while the hike table gives 1154 feet for the base overlook route. No single elevation gain is published here.',mh),conflict('difficulty','Quick facts say Moderately strenuous to Strenuous; the base-route table says Moderate. Difficulty remains unclassified here because those ratings differ.',mh)],tags=['historic','forest','overlook','hiking'])
add('hafe','Murphy-Chambers Farm Trail','trail',mc,'Walk through fields and wooded ravines to Shenandoah River views, Civil War earthworks and a former location of John Brown’s Fort. Side trails extend the core farm walk into additional river overlooks.',['1 - 3 miles','187 feet','fields and wooded ravines'],length=length(1,'minimum round-trip option in the NPS 1–3-mile range; optional side trails extend the walk to 3 miles'),difficulty='Easy to Moderate',elevationGain=gain(187,'NPS trail quick facts; gain is not assigned separately to every optional side trail'),terrain='Fields, ravines, mulched trail and a footbridge on a side branch.',tags=['historic','river','overlook','hiking'])
add('hafe','Schoolhouse Ridge North Trail','trail',sn,'Explore rolling farm fields from the Confederate side of the 1862 battle landscape. Cannons and views toward Bolivar Heights and Maryland Heights help explain the surrounding military terrain.',['1.7 miles','2.1 miles','110 feet','little to no shade'],difficulty='Easy to Moderate in quick facts; Moderate in the narrative',elevationGain=gain(110,'NPS trail quick facts'),terrain='Rolling open fields with little shade.',conflicts=[conflict('length','The same official page gives 1.7 miles round trip in quick facts and 2.1 miles round trip in its narrative. Distance is deliberately omitted until the route definitions are reconciled.',sn)],tags=['historic','battlefield','hiking'])
add('hafe','Visitor Center to Lower Town Trail','trail',vc,'Walk from the visitor center through a steep ravine, wetlands and remnants of the Shenandoah Pulp Mill and canal. The trail offers a walking alternative to the shuttle, with a road crossing and a strenuous uphill return.',['1.6 miles','97 stone steps','150 feet downhill'],length=length(1.6,'one way from the visitor center to Lower Town; return not included'),routeType='one-way segment',terrain='97 stone steps, a steep ravine and a road crossing; source describes 150 feet of descent, not total elevation gain.',accessibility='The stone staircase and strenuous uphill return are important mobility barriers; this is not represented as an accessible alternative to the shuttle.',conflicts=[conflict('difficulty','Quick facts describe Easy with one strenuous section; narrative describes Moderate due to one steep section. No single simplified rating is assigned.',vc)],tags=['historic','river','waterfall','hiking'])
add('hafe',"John Brown's Fort",'historic-site','places/john-brown-s-fort.htm','The former armory fire-engine house became John Brown’s final stronghold during the 1859 raid. Its later moves, including a period at Storer College, form part of the site’s history of emancipation and remembrance.',['1859','Storer College'],tags=['historic','civil-rights'])
add('hafe','Storer College','historic-site','hafe/learn/historyculture/storer-college.htm','Explore the story of a post-Civil War school that grew from education for formerly enslaved people into a college open across race and gender. The Camp Hill campus connects education, community building and resistance to segregation.',['formerly enslaved','Camp Hill'],tags=['historic','civil-rights','education'])

bg='choh/planyourvisit/billy-goat-trail.htm'
add('choh','Billy Goat Trail Section A','trail',bg,'Scramble over angled rock and boulders above Mather Gorge and the Potomac. NPS recommends downstream travel; the towpath return is separate from the scrambling section.',['Section A','1.75 miles one way','1.7 mile hike'],difficulty='Technical and Strenuous',routeType='one-way segment',terrain='Angled rocks, boulders and climbing; narrow exposed passages.',duration='2–3 hours for the scrambling section, as described by NPS.',seasonalNotes='Flooding can close this section. Verify the official Current Conditions page before hiking.',conflicts=[conflict('length','The fact box states 1.75 miles one way, while prose states 1.7 miles. Both measurements are retained here; a single numeric distance is omitted rather than selecting one.',bg)],tags=['river','geology','overlook','hiking'])
add('choh','Billy Goat Trail Section B','trail',bg,'Follow a quieter Potomac-side route with small rock scrambles and spring birding opportunities. The section is reached from the towpath near the Anglers access area.',['Section B','1.4 miles one way','birding'],length=length(1.4,'one way along Section B; excludes connecting towpath travel'),difficulty='Moderate',terrain='Small rock scrambles.',tags=['river','birding','hiking'])
add('choh','Billy Goat Trail Section C','trail',bg,'Walk wooded terrain past Potomac views and a small waterfall near Carderock. Rock outcrops remain part of the route even though most of the trail runs through forest.',['Section C','1.6 miles one way','small waterfall'],length=length(1.6,'one way along Section C; excludes connecting towpath travel'),difficulty='Easy to Moderate',terrain='Mostly wooded with rock outcrops.',tags=['river','forest','waterfall','hiking'])
add('blue','Bluestone Turnpike Trail','trail','places/bluestone-turnpike-trail.htm','Follow an old riverbank road through forest and wildlife habitat between access points near Bluestone and Pipestem state parks. Remnants of Lilly and former farms connect the river corridor to its human history.',['9.5 miles (one way)','Moderate','town site of Lilly'],length=length(9.5,'one way for the full turnpike trail; shorter ranger walks are different itineraries'),difficulty='Moderate',duration='4–5 hours, as published by NPS.',terrain='Riverbank road with small hills and sections of rough or muddy footing.',permitNotes='The official trail description prohibits overnight camping in this area. Verify access arrangements at the state-park endpoints.',tags=['river','forest','historic','hiking'])

cb='indu/planyourvisit/cb16.htm';cd='indu/planyourvisit/cd16.htm';dr='indu/planyourvisit/dr16.htm';gm='indu/planyourvisit/gm16.htm';outer='places/bailly-homestead-chellberg-farm-little-calumet-river-mnoke-prairie-trails.htm'
add('indu','Cowles Bog Trail','trail',cb,'Cross wetlands, black oak savanna and interdunal ponds before climbing loose-sand dunes to Lake Michigan. The featured lollipop route returns via the beach and wetland-edge trail; the cut-off avoids both the dune climb and the lake.',['4.7 miles, 202 feet','lollipop shaped','41.645191, -87.084633'],length=length(4.7,'complete NPS featured lollipop hike from the main north lot, including the return spur'),routeType='lollipop',difficulty='Moderate to rugged with steep dune climbs in loose sand',elevationGain=gain(202,'total gain for the 4.7-mile NPS featured hike'),surface='Loose sand and packed dirt.',accessibility='NPS states the trail is not wheelchair accessible.',latitude=41.645191,longitude=-87.084633,locationKind='Trailhead: main north parking lot',locationSource=u(cb),tags=['forest','lake','wetland','hiking'])
add('indu','Calumet Dunes Trail','trail',cd,'Follow a paved loop along a former Lake Michigan shoreline ridge. Connections lead toward other dune systems, while the featured circuit returns around the former visitor-center building.',['0.5 miles, 32 feet','loop trail','41.661836, -87.010109','slopes exceed ADA limits'],length=length(.5,'entire NPS featured loop'),routeType='loop',difficulty='Easy with some elevation change',elevationGain=gain(32,'NPS featured half-mile loop'),surface='Paved.',accessibility='NPS says slopes exceed ADA limits and wheelchair access may require support; the featured-hike description calls the loop wheelchair accessible. Do not infer suitability from pavement alone.',latitude=41.661836,longitude=-87.010109,locationKind='Trailhead parking lot',locationSource=u(cd),tags=['geology','forest','hiking'])
add('indu','Dune Ridge Trail','trail',dr,'A short lollipop route crosses sandy foredunes and oak savanna before reaching views over Great Marsh. The return descends a steep loose-sand slope and rejoins the approach path.',['0.7 miles, 73 feet','lollipop shaped','41.677357, -87.008950'],length=length(.7,'entire NPS featured lollipop hike, including the return spur'),routeType='lollipop',difficulty='Moderate with some steep slopes in loose sand',elevationGain=gain(73,'NPS featured 0.7-mile hike'),surface='Loose sand and packed dirt.',accessibility='NPS states trails are not wheelchair accessible; accessible restrooms do not make the route accessible.',latitude=41.677357,longitude=-87.008950,locationKind='Dune Ridge trailhead / Kemil Beach parking lot',locationSource=u(dr),tags=['overlook','wetland','forest','hiking'])
add('indu','Great Marsh Trail','trail',gm,'Explore the restored wetland habitat used by waterfowl, wading birds and migrating songbirds. The main route starts at the south lot; a separate paved approach from the north lot reaches an observation deck.',['Hike Length – 1.3 miles','South Lot: 41.674825, -86.986607','main trail is not wheelchair accessible'],length=length(1.3,'published main-hike length; guide does not establish a one-way versus round-trip basis'),difficulty='Easy with no change in elevation',surface='Packed dirt and grass with gravel sections; can be wet and muddy.',accessibility='Main trail is not wheelchair accessible. A separate paved wheelchair-accessible trail reaches the overlook from the north lot; 1.3 miles must not be assigned to that accessible subsection.',latitude=41.674825,longitude=-86.986607,locationKind='Main trailhead: south parking lot (not the accessible north approach)',locationSource=u(gm),tags=['birding','wetland','hiking'])
add('indu','Bailly–Chellberg / Little Calumet–Mnoké Outer Loop','trail',outer,'Combine woodland ravines, a Little Calumet River crossing and restored prairie with the Bailly Homestead and Chellberg Farm landscape. This is the featured perimeter hike, not a sum of every trail in the system.',['Outer Loop Trail','3.4 miles, 120 feet','41.624679, -87.089502','perimeter loop hike'],length=length(3.4,'NPS featured outer perimeter loop; excludes the optional 0.6-mile cemetery extension'),routeType='loop',difficulty='Easy to moderate with elevation changes and stairs',elevationGain=gain(120,'NPS featured outer loop'),surface='Packed soil with wood chips in places; stairs and muddy sections.',accessibility='NPS says the trails are not wheelchair accessible; accessible restrooms and picnic facilities are separate amenities.',latitude=41.624679,longitude=-87.089502,locationKind='Bailly / Chellberg trailhead parking lot',locationSource=u(outer),tags=['historic','forest','river','prairie','hiking'])
add('indu','Bailly Homestead','historic-site','indu/learn/historyculture/bailly_homestead.htm','Historic log and brick buildings interpret Joseph and Marie Bailly’s trading, family and community history where Indigenous travel routes met the Little Calumet River. The site places settlement and trade within the Potawatomi homeland.',['Marie Le Fevre','Potawatomi Nation'],tags=['historic','cultural-landscape'])
add('indu','Chellberg Farm','historic-site','indu/learn/historyculture/chellberg-farm.htm','A brick farmhouse, timber-framed barn and farm buildings preserve the story of a Swedish immigrant family in Baillytown. Interior access depends on official programs rather than being guaranteed by a general park visit.',['Swedish immigrant','farmhouse is open to the public during'],accessibility='The farmhouse has a short access ramp and an accessible approach trail as described by NPS; scheduled interior access must be checked separately.',tags=['historic','agriculture'])

pi='piro/planyourvisit/hikes.htm'
add('piro','Sand Point Marsh Trail','trail',pi,'A boardwalk loop passes old beach ridges, cattails, ponds and cedar–spruce swamp near Sand Point Beach. The wetland setting offers wildlife observation without a long backcountry hike.',['Sand Point Marsh Trail','0.5 mile loop','wheelchair-accessible'],length=length(.5,'entire boardwalk loop'),routeType='loop',surface='Boardwalk.',accessibility='The official hiking guide identifies this boardwalk trail as wheelchair accessible.',tags=['wetland','birding','hiking'])
add('piro','Log Slide Overlook Trail','trail',pi,'Walk through mature hardwoods to the edge of Grand Sable Dunes, where a former logging chute once carried timber toward Lake Superior. Views extend toward the dunes and Au Sable lighthouse.',['Log Slide Overlook Trail','0.25 miles roundtrip','platform was destroyed'],length=length(.25,'round trip to the overlook area'),surface='Forest path.',seasonalNotes='The retained guide says the former overlook platform was destroyed; the path to its location remains described. Check current conditions and do not assume an intact platform.',tags=['historic','overlook','forest','hiking'])
add('piro','Miners Falls Trail','trail',pi,'A forest walk leads to a sandstone waterfall on the Miners River. A lower viewing platform requires an additional descent by stairs, so the approach and lower viewpoint have different mobility demands.',['Miners Falls Trail','1.2 miles roundtrip','64 steps'],length=length(1.2,'round trip on the Miners Falls route'),difficulty='Easy, fairly level',accessibility='The lower platform requires 64 additional steps; the fairly level approach is not a claim of full wheelchair accessibility.',tags=['waterfall','forest','geology','hiking'])
add('piro','Chapel Falls','trail',pi,'Follow an old roadbed through upland maple forest to Chapel Falls. This short destination hike stops at the waterfall rather than continuing to Chapel Beach or completing the much longer cliff loop.',['Chapel Falls','2.5 miles roundtrip','old roadbed'],length=length(2.5,'round trip from Chapel parking lot to Chapel Falls; not the Chapel Beach or Chapel Loop hike'),difficulty='Easy',surface='Old roadbed through upland maple forest.',tags=['waterfall','forest','hiking'])
add('piro','Miners Castle','overlook','places/miners-castle.htm','View a sandstone cliff formation and Lake Superior from the park’s drive-accessible cliff area. Upper overlooks and the lower platform have different approaches, and a 2006 rockfall changed the formation’s outline.',['two breathtaking overlooks','Stairs and a steeper trail','2006'],accessibility='A paved wheelchair-accessible path reaches the upper overlooks; the lower overlook requires stairs and a steep incline.',tags=['geology','overlook','lake'])
add('piro','Au Sable Light Station','historic-site','piro/planyourvisit/au-sable.htm','Visit the isolated Lake Superior light station and learn how keepers served shipping along this hazardous shoreline. The lighthouse climb is a separate ranger activity involving a long staircase.',['98 steps','Assistant Keeper'],accessibility='The lighthouse climb involves 98 steps. Check official tour arrangements; the station grounds and tower climb are not equivalent experiences.',tags=['historic','lighthouse','lake'])

ma='maca/planyourvisit/accessible-activities.htm';mg='maca/planyourvisit/visitor-center-area-and-south-side-trails.htm';hm='thingstodo/heritage-trail.htm';news='maca/learn/news/heritage-trail-rehabilitation-project-for-mammoth-cave-national-park.htm';mapg='maca/planyourvisit/mammoth-cave-map-guide.htm'
add('maca','Cedar Sink Trail','trail','thingstodo/cedar-sink-trail.htm','Descend into a large sinkhole on a forest trail known for seasonal wildflowers. The route reveals surface karst geology and includes substantial stair travel into and out of the sink.',['1-mile roundtrip','295 stairs','loop trail'],related=[mapg],length=length(1,'round trip as stated by the individual activity page'),terrain='Rolling dirt approach and 295 stairs over the hike.',accessibility='NPS describes a roughly six-foot-wide dirt approach and a descent of about 150 feet by stairs into the sink, followed by a climb out. This is not an accessible route.',conflicts=[conflict('routeType','The individual activity page calls the hike a loop; the park map guide calls Cedar Sink a short out-and-back hike. Route type is left unspecified.', 'thingstodo/cedar-sink-trail.htm',mapg)],tags=['geology','forest','wildflowers','hiking'])
add('maca','Sand Cave Trail','trail',ma,'A short interpretive boardwalk recounts Floyd Collins’ fatal 1925 entrapment and rescue attempt at Sand Cave. The outdoor route leads toward the historic site rather than providing a cave tour.',['Sand Cave Trail','0.1 mile boardwalk','Floyd Collins'],related=[mapg],length=length(.1,'published boardwalk approach length; NPS does not explicitly state whether this number includes the return'),routeType='out-and-back',surface='Boardwalk.',accessibility='Listed by NPS among accessible self-guided adventures, with accessible parking at the eastern entrance sign.',tags=['historic','geology','hiking'])
add('maca','Heritage Trail','trail',hm,'A ridge-top walk reaches views over the Green River Valley and links the visitor-center area with the Old Guides Cemetery and historic cave landscape. Conflicting published measurements and rehabilitation information require checking the official source before planning.',['.6-mile','Sunset point','Accessibility Information'],related=[mg,news],routeType='out-and-back',accessibility='NPS identifies an accessible trail, but the older activity page’s wood-and-cement surface description predates the rehabilitation project. Verify current access and surface information.',seasonalNotes='The retained visitor-area guide reports a rehabilitation closure, while an archived 2025 release gives an expected completion date. Neither is a verified current opening notice.',conflicts=[conflict('length','The individual activity page gives 0.6 mile out-and-back, while the visitor-area table and 2025 rehabilitation release give 0.5 mile. A numeric distance is intentionally omitted.',hm,mg,news),conflict('surface','The 2020 activity description lists raised wooden walkway and cement. The 2025 project planned replacement with hardened cement; completion and final surface were not independently verified.',hm,news)],tags=['historic','overlook','forest','hiking'])

hp='hocu/learn/historyculture/hopewell-mound-group.htm';ht='thingstodo/hiking-exploring-hopewell-mound-group.htm'
add('hocu','Hopewell Mound Group trails','trail',ht,'Walk the earthwork landscape and woodland to surviving sections of the original ceremonial enclosure. The source describes gravel and mulch paths with elevation changes; published mileage elsewhere on the official site is inconsistent.',['2.5 miles','Narrow, wooden bridge'],related=[hp],length=length(2.5,'approximate site trail distance from the NPS activity introduction; an official history page also describes a two-mile interpretive trail, so route extent is uncertain'),difficulty='Easy to Moderate',accessibility='Only a short sidewalk from the parking area is paved. Other trails use mulch, pebbled dirt, or grass and include elevation changes and a narrow wooden bridge.',tags=['hiking','earthworks','woodland','historic','forest'],conflicts=[conflict('length','The activity introduction and history-page introduction describe 2.5 miles, but the history page Visiting the Site section says two miles. It is unclear whether different route extents are intended; the existing approximate 2.5-mile value is retained with this limitation.',ht,hp)])
add('hocu','Hopewell Mound Group','historic-site',hp,'Explore the archaeological landscape that gave the Hopewell culture its modern name. Most monumental earthworks were reduced by farming and excavation, but surviving wall remnants and interpretation help reveal the scale of the ceremonial enclosure.',['type site','six-foot-high section'],tags=['historic','earthworks','Indigenous heritage'])
add('hocu','Seip Earthworks','historic-site','places/seip.htm','A restored central mound, a reconstructed section of enclosure and interpretive waysides reveal part of a much larger ceremonial earthwork complex. The self-guided landscape visit is distinct from viewing excavated objects in a museum.',['restored central mound','Interpretive trails and waysides'],tags=['historic','earthworks','Indigenous heritage'])

(E/'release0710-trails.json').write_text(json.dumps(OUT,ensure_ascii=False,indent=2)+'\n')
print('Reviewed',sum(len(p['attractions']) for p in OUT['parks'].values()),'records across',len(OUT['parks']),'units')
